/**
 * Populate .sandcastle/.env from local provider credentials.
 * Never prints secret values.
 */
import { existsSync, readFileSync, writeFileSync } from 'node:fs';
import { homedir } from 'node:os';
import { join } from 'node:path';

const root = process.cwd();
const envPath = join(root, '.sandcastle', '.env');
const lines = [
  '# Auto-generated by scripts/sync-sandcastle-env.mjs — do not commit.',
  '',
];

let openaiSet = false;
const codexAuthPath = join(homedir(), '.codex', 'auth.json');
if (existsSync(codexAuthPath)) {
  try {
    const auth = JSON.parse(readFileSync(codexAuthPath, 'utf8'));
    const apiKey = auth.OPENAI_API_KEY || auth.tokens?.access_token;
    if (typeof apiKey === 'string' && apiKey.length > 0) {
      lines.push(`OPENAI_API_KEY=${apiKey}`);
      openaiSet = true;
    }
  } catch {
    // Ignore malformed auth.json.
  }
}
if (!openaiSet) {
  lines.push('# No Codex credential found in ~/.codex/auth.json');
  lines.push('OPENAI_API_KEY=');
}

let cursorSet = false;
for (const candidate of [
  join(homedir(), '.cursor', '.env'),
  join(root, '.env'),
]) {
  if (!existsSync(candidate)) {
    continue;
  }
  const match = readFileSync(candidate, 'utf8').match(/^CURSOR_API_KEY=(.+)$/m);
  if (match?.[1]?.trim()) {
    lines.push(`CURSOR_API_KEY=${match[1].trim()}`);
    cursorSet = true;
    break;
  }
}
if (!cursorSet) {
  lines.push('# Generate at https://cursor.com/dashboard → Integrations → User API Keys');
  lines.push('CURSOR_API_KEY=');
}

writeFileSync(envPath, `${lines.join('\n')}\n`, { mode: 0o600 });
process.stderr.write(
  `Wrote ${envPath} (OPENAI: ${openaiSet ? 'yes' : 'no'}, CURSOR: ${cursorSet ? 'yes' : 'no'})\n`,
);
